class IssuerBreaker {
    private volatile int consecutiveFailures;   // written by request threads
    private volatile long openedAtMillis;       // 0 means closed

    void onFailure(long now) {
        consecutiveFailures++;                                             // 1. read-modify-write
        if (consecutiveFailures >= 5 && openedAtMillis == 0) openedAtMillis = now;   // 2. check-then-act
    }

    void onSuccess() { consecutiveFailures = 0; }

    boolean allowRequest(long now) {
        long opened = openedAtMillis;
        return opened == 0 || now - opened > 30_000;
    }
}

