class IssuerBreaker {
    private final AtomicInteger consecutiveFailures = new AtomicInteger();   // 1. many writers: atomic
    private volatile long openedAtMillis;                                    // 2. readers need one value: volatile

    void onFailure(long now) {
        int n = consecutiveFailures.incrementAndGet();   // 3. one atomic step, and keep the result
        if (n == 5) openedAtMillis = now;                // 4. only one thread sees n == 5
    }

    void onSuccess() { consecutiveFailures.set(0); }

    boolean allowRequest(long now) {
        long opened = openedAtMillis;                    // 5. read the volatile once
        return opened == 0 || now - opened > 30_000;
    }
}

