// one writer, readers need the latest value: volatile is enough
public final class KafkaLagGauge {
    private volatile long lag;   // volatile also keeps the 64-bit write in one piece

    public void update(long newLag) { lag = newLag; }
    public long lag() { return lag; }
}

// many writers doing read-modify-write: atomic (LongAdder if it is very hot)
public final class RetryCounter {
    private final AtomicLong count = new AtomicLong();

    public void onRetry() { count.incrementAndGet(); }
    public long retries() { return count.get(); }
}

